<?php
namespace App\Controllers;
class AdminDashboardController extends BaseController { public function index():string{$db=\Config\Database::connect();return view('admin/dashboard',['title'=>'Dashboard','total'=>$db->table('students')->countAllResults(),'enrolled'=>$db->table('students')->where('enrollment_status','enrolled')->countAllResults(),'successful'=>$db->table('verification_logs')->where('verification_result','verified')->countAllResults(),'unsuccessful'=>$db->table('verification_logs')->where('verification_result !=','verified')->countAllResults(),'requests'=>$db->table('verification_assistance_requests')->countAllResults()]);}}
